// XSTAR-FUNCTION-COMMENT-BEGIN
// Purpose: Implement split csv simple in the standalone controller/front-end workflow without duplicating the scientific kernels.
// Reference context: XSTAR Manual ch14 for controller/radial workflow; implementation helper unless the called shared core performs the physics.
// XSTAR-FUNCTION-COMMENT-END
std::vector<std::string> split_csv_simple(const std::string& line) {
    std::vector<std::string> fields;
    std::string field;
    std::istringstream input(line);
    while (std::getline(input, field, ',')) fields.push_back(field);
    return fields;
}

// XSTAR-FUNCTION-COMMENT-BEGIN
// Purpose: Compute attach native thermal families as a contribution to, or control step in, the local thermal-equilibrium iteration.
// Reference context: XSTAR Manual s11.4.4 and s11.6; Kallman & Bautista (2001).
// XSTAR-FUNCTION-COMMENT-END
void attach_native_thermal_families(
    std::vector<FixedDsecSnapshot>& snapshots,
    const std::filesystem::path& path) {
    std::ifstream input(path);
    if (!input) throw std::runtime_error("cannot open native thermal-family ledger: " + path.string());
    std::string header;
    std::getline(input, header);
    const auto names = split_csv_simple(header);
    std::map<std::string,std::size_t> columns;
    for (std::size_t i = 0; i < names.size(); ++i) columns[names[i]] = i;
    for (const char* required : {"sequence","h_heating","h_cooling","he_heating","he_cooling",
             "mg_heating","mg_cooling","htcomp","clcomp","clbrems"}) {
        if (!columns.count(required)) throw std::runtime_error(std::string("thermal ledger missing column: ") + required);
    }
    std::map<std::size_t,FixedDsecSnapshot*> by_sequence;
    for (auto& snapshot : snapshots) by_sequence[snapshot.sequence] = &snapshot;
    std::string line;
    std::size_t attached = 0;
    while (std::getline(input, line)) {
        if (line.empty()) continue;
        const auto values = split_csv_simple(line);
        const std::size_t sequence = static_cast<std::size_t>(std::stoull(values.at(columns.at("sequence"))));
        const auto found = by_sequence.find(sequence);
        if (found == by_sequence.end()) continue;
        auto& s = *found->second;
        auto scalar = [&](const char* name) { return std::stod(values.at(columns.at(name))); };
        s.hydrogen_heating = scalar("h_heating");
        s.hydrogen_cooling = scalar("h_cooling");
        s.helium_heating = scalar("he_heating");
        s.helium_cooling = scalar("he_cooling");
        s.magnesium_heating = scalar("mg_heating");
        s.magnesium_cooling = scalar("mg_cooling");
        s.compton_heating = scalar("htcomp");
        s.compton_cooling = scalar("clcomp");
        s.brems_cooling = scalar("clbrems");
        s.thermal_families_native = true;
        ++attached;
    }
    if (attached != snapshots.size()) {
        throw std::runtime_error("native thermal-family ledger did not cover all 61 evaluations");
    }
}

struct CallStartWorkspace {
    std::vector<double> radiation_energy;
    std::vector<double> bremsa;
    std::vector<double> continuum_tau_in;
    std::vector<double> continuum_tau_out;
    std::vector<double> global_xilevg;
    std::vector<double> global_bilevg;
    std::vector<double> global_rnisg;
};

// 0.6.82.40.2.11: production only needs the current call-start payload.
// Historical full payloads were retained by call number and grew ~4.76 MiB
// per low-xi radial zone. Reference-trajectory/audit modes keep the old
// lifetime exactly; generic production releases completed payloads.
std::uint64_t call_start_workspace_capacity_bytes_v068240211(const CallStartWorkspace& w) {
    return static_cast<std::uint64_t>(
        w.radiation_energy.capacity() + w.bremsa.capacity() +
        w.continuum_tau_in.capacity() + w.continuum_tau_out.capacity() +
        w.global_xilevg.capacity() + w.global_bilevg.capacity() +
        w.global_rnisg.capacity()) * sizeof(double);
}

std::uint64_t release_call_start_workspace_payload_v068240211(CallStartWorkspace& w) {
    const std::uint64_t before = call_start_workspace_capacity_bytes_v068240211(w);
    std::vector<double>().swap(w.radiation_energy);
    std::vector<double>().swap(w.bremsa);
    std::vector<double>().swap(w.continuum_tau_in);
    std::vector<double>().swap(w.continuum_tau_out);
    std::vector<double>().swap(w.global_xilevg);
    std::vector<double>().swap(w.global_bilevg);
    std::vector<double>().swap(w.global_rnisg);
    return before;
}

// 0.6.82.40.2.12: transfer vector ownership without deallocation.
// The next call reuses the exact capacity, avoiding .2.11 allocator churn.
void swap_call_start_workspace_payload_v068240212(
    CallStartWorkspace& a, CallStartWorkspace& b) {
    a.radiation_energy.swap(b.radiation_energy);
    a.bremsa.swap(b.bremsa);
    a.continuum_tau_in.swap(b.continuum_tau_in);
    a.continuum_tau_out.swap(b.continuum_tau_out);
    a.global_xilevg.swap(b.global_xilevg);
    a.global_bilevg.swap(b.global_bilevg);
    a.global_rnisg.swap(b.global_rnisg);
}

std::uint64_t call_start_workspaces_capacity_bytes_v068240211(
    const std::vector<CallStartWorkspace>& workspaces) {
    std::uint64_t total = static_cast<std::uint64_t>(workspaces.capacity()) * sizeof(CallStartWorkspace);
    for (const auto& w : workspaces) total += call_start_workspace_capacity_bytes_v068240211(w);
    return total;
}

