// XSTAR-FUNCTION-COMMENT-BEGIN
// Purpose: Implement physical run search roots in the standalone controller/front-end workflow without duplicating the scientific kernels.
// Reference context: XSTAR Manual ch14 for controller/radial workflow; implementation helper unless the called shared core performs the physics.
// XSTAR-FUNCTION-COMMENT-END
std::vector<std::filesystem::path> physical_run_search_roots(const Options& options) {
    std::vector<std::filesystem::path> roots;
    auto add = [&](std::filesystem::path path) {
        if (path.empty()) return;
        std::error_code ec;
        path = std::filesystem::absolute(path, ec);
        if (ec) return;
        for (const auto& existing : roots) if (existing == path) return;
        roots.push_back(path);
    };
    add(std::filesystem::current_path());
    if (!options.parameters_path.empty()) add(std::filesystem::path(options.parameters_path).parent_path());
    const auto executable_dir = xstar_standalone::executable_or_library_directory(
        reinterpret_cast<const void*>(&xstar_api_abi_version));
    add(executable_dir);
    const std::size_t initial = roots.size();
    for (std::size_t i = 0; i < initial; ++i) {
        auto parent = roots[i];
        for (int level = 0; level < 5 && parent.has_parent_path(); ++level) {
            parent = parent.parent_path();
            add(parent);
        }
    }
    return roots;
}

// XSTAR-FUNCTION-COMMENT-BEGIN
// Purpose: Implement first existing path in the standalone controller/front-end workflow without duplicating the scientific kernels.
// Reference context: XSTAR Manual ch14 for controller/radial workflow; implementation helper unless the called shared core performs the physics.
// XSTAR-FUNCTION-COMMENT-END
std::filesystem::path first_existing_path(
    const std::vector<std::filesystem::path>& candidates, bool directory) {
    for (const auto& candidate : candidates) {
        std::error_code ec;
        const bool present = directory
            ? std::filesystem::is_directory(candidate, ec)
            : std::filesystem::is_regular_file(candidate, ec);
        if (!ec && present) return std::filesystem::absolute(candidate);
    }
    return {};
}

// XSTAR-FUNCTION-COMMENT-BEGIN
// Purpose: Implement environment path in the standalone controller/front-end workflow without duplicating the scientific kernels.
// Reference context: XSTAR Manual ch14 for controller/radial workflow; implementation helper unless the called shared core performs the physics.
// XSTAR-FUNCTION-COMMENT-END
std::filesystem::path environment_path(const char* name, bool directory) {
    const char* value = std::getenv(name);
    if (!value || !*value) return {};
    return first_existing_path({std::filesystem::path(value)}, directory);
}

// XSTAR-FUNCTION-COMMENT-BEGIN
// Purpose: Implement sibling release roots in the standalone controller/front-end workflow without duplicating the scientific kernels.
// Reference context: XSTAR Manual ch14 for controller/radial workflow; implementation helper unless the called shared core performs the physics.
// XSTAR-FUNCTION-COMMENT-END
std::vector<std::filesystem::path> sibling_release_roots(
    const std::vector<std::filesystem::path>& roots) {
    std::vector<std::filesystem::path> packages;
    for (const auto& root : roots) {
        std::error_code ec;
        if (!std::filesystem::is_directory(root, ec) || ec) continue;
        for (std::filesystem::directory_iterator it(root, ec), end; !ec && it != end; it.increment(ec)) {
            if (ec || !it->is_directory(ec) || ec) continue;
            const std::string name = it->path().filename().string();
            if (name.rfind("xstar_tools-", 0) != 0) continue;
            packages.push_back(std::filesystem::absolute(it->path()));
        }
    }
    std::sort(packages.begin(), packages.end(), [](const auto& left, const auto& right) {
        return left.filename().string() > right.filename().string();
    });
    packages.erase(std::unique(packages.begin(), packages.end()), packages.end());
    return packages;
}

// XSTAR-FUNCTION-COMMENT-BEGIN
// Purpose: Compute resolve physical asset as part of the multilevel statistical-equilibrium system and its normalization/detailed-balance constraints.
// Reference context: XSTAR Manual ss11.4.1-11.4.3; Kallman & Bautista (2001); Bautista & Kallman (2001).
// XSTAR-FUNCTION-COMMENT-END
std::filesystem::path resolve_physical_asset(
    const std::string& explicit_value,
    const char* environment_name,
    const std::vector<std::filesystem::path>& roots,
    const std::vector<std::filesystem::path>& relative_candidates,
    bool directory) {
    if (!explicit_value.empty()) {
        return first_existing_path({std::filesystem::path(explicit_value)}, directory);
    }
    if (const auto env = environment_path(environment_name, directory); !env.empty()) return env;
    std::vector<std::filesystem::path> candidates;
    // Candidate priority is semantic: test every search root for the preferred
    // source before considering a lower-priority fallback source.
    for (const auto& relative : relative_candidates) {
        for (const auto& root : roots) candidates.push_back(root / relative);
    }
    // Product qualification depends on artifacts produced by the accepted predecessor
    // release.  Search sibling xstar_tools-* trees deterministically so a clean source
    // release can consume the qualified v21.17.2 closure without manual overrides.
    for (const auto& package_root : sibling_release_roots(roots)) {
        for (const auto& relative : relative_candidates) candidates.push_back(package_root / relative);
    }
    return first_existing_path(candidates, directory);
}



// XSTAR-FUNCTION-COMMENT-BEGIN
// Purpose: Load text file into the typed runtime representation, validating the fields needed by downstream source-faithful calculations.
// Reference context: XSTAR Manual ch14 (workflow/state lifetime) and ch5 (final products); orchestration helper.
// XSTAR-FUNCTION-COMMENT-END
std::string read_text_file(const std::filesystem::path& path) {
    std::ifstream in(path);
    if (!in) return {};
    return std::string((std::istreambuf_iterator<char>(in)), std::istreambuf_iterator<char>());
}

// XSTAR-FUNCTION-COMMENT-BEGIN
// Purpose: Implement json number value in the standalone controller/front-end workflow without duplicating the scientific kernels.
// Reference context: XSTAR Manual ch14 for controller/radial workflow; implementation helper unless the called shared core performs the physics.
// XSTAR-FUNCTION-COMMENT-END
double json_number_value(const std::string& text, const std::string& key, double fallback) {
    try {
        const std::regex re("\\\"" + key + "\\\"\\s*:\\s*(?:\\\"([^\\\"]*)\\\"|([-+0-9.eE]+))");
        std::smatch m;
        if (!std::regex_search(text, m, re)) return fallback;
        const std::string v = m[1].matched ? m[1].str() : m[2].str();
        if (v.empty()) return fallback;
        return std::stod(v);
    } catch (...) { return fallback; }
}

// XSTAR-FUNCTION-COMMENT-BEGIN
// Purpose: Implement json string value in the standalone controller/front-end workflow without duplicating the scientific kernels.
// Reference context: XSTAR Manual ch14 for controller/radial workflow; implementation helper unless the called shared core performs the physics.
// XSTAR-FUNCTION-COMMENT-END
std::string json_string_value(const std::string& text, const std::string& key, const std::string& fallback) {
    try {
        const std::regex re("\\\"" + key + "\\\"\\s*:\\s*\\\"([^\\\"]*)\\\"");
        std::smatch m;
        if (!std::regex_search(text, m, re)) return fallback;
        return m[1].str();
    } catch (...) { return fallback; }
}


// XSTAR-FUNCTION-COMMENT-BEGIN
// Purpose: Preserve declared public source-input files when file-silent production verifies that it created no non-product artifacts.
// Reference context: XSTAR rread1.f90 opens density.dat and spectrum_file from the working directory; those are inputs, not generated products.
// XSTAR-FUNCTION-COMMENT-END
void add_public_source_input_allowances_v0682281(
    std::set<std::string>& allowed,
    const std::filesystem::path& output,
    const std::filesystem::path& parameters_path) {
    const std::string publication_json = read_text_file(parameters_path);
    if (json_number_value(publication_json, "radexp", 0.0) < -99.0) {
        const auto density = output / "density.dat";
        if (std::filesystem::is_regular_file(density)) allowed.insert("density.dat");
    }
    std::string spectrum_mode = json_string_value(publication_json, "spectrum", "pow");
    std::transform(spectrum_mode.begin(), spectrum_mode.end(), spectrum_mode.begin(),
        [](unsigned char c) { return static_cast<char>(std::tolower(c)); });
    if (spectrum_mode != "file") return;

    std::filesystem::path declared(json_string_value(publication_json, "spectrum_file", "spct.dat"));
    if (declared.empty()) declared = "spct.dat";
    std::filesystem::path candidate = declared.is_absolute() ? declared : output / declared;
    std::error_code output_ec, candidate_ec;
    const auto output_abs = std::filesystem::weakly_canonical(output, output_ec);
    const auto candidate_abs = std::filesystem::weakly_canonical(candidate, candidate_ec);
    if (output_ec || candidate_ec || !std::filesystem::is_regular_file(candidate_abs)) return;
    // The top-level file-silent artifact scan sees only direct children of the
    // output directory. Allow the declared spectrum input only when it is
    // exactly such a child; an external absolute input needs no exemption.
    if (candidate_abs.parent_path() == output_abs) allowed.insert(candidate_abs.filename().string());
}

// XSTAR-FUNCTION-COMMENT-BEGIN
// Purpose: Implement float bits local in the standalone controller/front-end workflow without duplicating the scientific kernels.
// Reference context: XSTAR Manual ch14 for controller/radial workflow; implementation helper unless the called shared core performs the physics.
// XSTAR-FUNCTION-COMMENT-END
std::uint32_t float_bits_local(float value) {
    std::uint32_t bits = 0;
    std::memcpy(&bits, &value, sizeof(bits));
    return bits;
}

// XSTAR-FUNCTION-COMMENT-BEGIN
// Purpose: Implement parameter row in the standalone controller/front-end workflow without duplicating the scientific kernels.
// Reference context: XSTAR Manual ch14 for controller/radial workflow; implementation helper unless the called shared core performs the physics.
// XSTAR-FUNCTION-COMMENT-END
xstar_run_state::ParameterRowState parameter_row(std::uint16_t index, const std::string& name, double value, const std::string& comment = "native standalone parameter") {
    xstar_run_state::ParameterRowState row;
    row.index = index;
    row.parameter = name;
    row.value_bits = float_bits_local(static_cast<float>(value));
    row.type = "float32";
    row.comment = comment;
    return row;
}

// XSTAR-FUNCTION-COMMENT-BEGIN
// Purpose: Implement public parameter row in the standalone controller/front-end workflow without duplicating the scientific kernels.
// Reference context: XSTAR Manual ch14 for controller/radial workflow; implementation helper unless the called shared core performs the physics.
// XSTAR-FUNCTION-COMMENT-END
xstar_run_state::ParameterRowState public_parameter_row(
    std::uint16_t index,
    const std::string& name,
    double value,
    const std::string& type,
    const std::string& comment = "") {
    xstar_run_state::ParameterRowState row;
    row.index = index;
    row.parameter = name;
    row.value_bits = float_bits_local(static_cast<float>(value));
    row.type = type;
    row.comment = comment;
    return row;
}

// XSTAR-FUNCTION-COMMENT-BEGIN
// Purpose: Implement native public parameter rows from json in the standalone controller/front-end workflow without duplicating the scientific kernels.
// Reference context: XSTAR Manual ch14 for controller/radial workflow; implementation helper unless the called shared core performs the physics.
// XSTAR-FUNCTION-COMMENT-END
std::vector<xstar_run_state::ParameterRowState> native_public_parameter_rows_from_json(
    const std::filesystem::path& parameters_path) {
    const std::string json = read_text_file(parameters_path);
    std::vector<xstar_run_state::ParameterRowState> rows;
    rows.reserve(59);
    const auto num = [&](const char* key, double fallback) { return json_number_value(json, key, fallback); };
    const auto str = [&](const char* key, const char* fallback) { return json_string_value(json, key, fallback); };
    const auto add_real = [&](const char* key, double fallback, const char* comment = "") {
        rows.push_back(public_parameter_row(static_cast<std::uint16_t>(rows.size() + 1), key, num(key, fallback), "real", comment));
    };
    const auto add_integer = [&](const char* key, double fallback, const char* comment = "") {
        rows.push_back(public_parameter_row(static_cast<std::uint16_t>(rows.size() + 1), key, num(key, fallback), "integer", comment));
    };
    const auto add_string = [&](const char* key, const char* fallback) {
        rows.push_back(public_parameter_row(static_cast<std::uint16_t>(rows.size() + 1), key, 0.0, "string", str(key, fallback)));
    };

    add_real("cfrac", 0.0);
    add_real("temperature", 400.0, "Units of 10**4 K");
    add_integer("lcpres", 0.0, "1=yes, 0=no");
    add_real("pressure", 0.03, "dynes/cm**2");
    add_real("density", 1.0e4, "cm**(-3)");
    add_string("spectrum", "pow");
    add_string("spectrum_file", "spct.dat");
    add_integer("spectun", 0.0, "0=energy, 1=photons, 2=log10 energy");
    add_real("trad", -1.0, "or alpha");
    add_real("rlrad38", 1.0e-6, "/10**38 erg/sec");
    add_real("column", 1.0e17, "cm**(-2)");
    add_real("rlogxi", 5.0);
    add_integer("nsteps", 3.0);
    add_integer("niter", 0.0);
    add_integer("lwrite", 0.0, "-1=spectrum-only, 0=standard, 1=detail");
    add_integer("lprint", 0.0, "1=yes, 0=no");
    add_integer("lstep", 0.0);
    add_string("abundtbl", "xdef");
    add_real("habund", 1.0);
    add_real("heabund", 1.0);
    add_real("liabund", 0.0);
    add_real("beabund", 0.0);
    add_real("babund", 0.0);
    add_real("cabund", 1.0);
    add_real("nabund", 1.0);
    add_real("oabund", 1.0);
    add_real("fabund", 1.0);
    add_real("neabund", 1.0);
    add_real("naabund", 1.0);
    add_real("mgabund", 1.0);
    add_real("alabund", 1.0);
    add_real("siabund", 1.0);
    add_real("pabund", 1.0);
    add_real("sabund", 1.0);
    add_real("clabund", 1.0);
    add_real("arabund", 1.0);
    add_real("kabund", 1.0);
    add_real("caabund", 1.0);
    add_real("scabund", 1.0);
    add_real("tiabund", 1.0);
    add_real("vabund", 1.0);
    add_real("crabund", 1.0);
    add_real("mnabund", 1.0);
    add_real("feabund", 1.0);
    add_real("coabund", 1.0);
    add_real("niabund", 1.0);
    add_real("cuabund", 1.0);
    add_real("znabund", 1.0);
    add_real("emult", 0.5);
    add_real("taumax", 5.0);
    add_real("xeemin", 0.1);
    add_real("critf", 1.0e-7);
    add_real("vturbi", 1.0);
    add_integer("npass", 1.0);
    add_string("modelname", "XSTAR Default");
    add_integer("loopcontrol", 0.0);
    // 0.6.82.23 public provenance extension beyond FORTRAN's historical 56
    // fparmlist rows.  Preserve the first 56 source order, append the three
    // xstar.par inputs that were previously absent from product metadata.
    add_real("radexp", 0.0);
    add_integer("ncn2", 9999.0);
    add_string("mode", "ql");
    return rows;
}

