// XSTAR-FUNCTION-COMMENT-BEGIN
// Purpose: Compute native line plane stride for the line/emissivity/opacity path on the source or publication energy grid.
// Reference context: XSTAR Manual ss11.5.1, 11.6-11.6.1; Kallman & Bautista (2001); data type 50 where applicable.
// XSTAR-FUNCTION-COMMENT-END
std::size_t native_line_plane_stride(
    const xstar_run_state::ExactSourceWorkspaceState& ws) {
    std::size_t stride = ws.oplin.size();
    if (ws.rcem.size() >= 2u) stride = std::max(stride, ws.rcem.size() / 2u);
    if (ws.tau0.size() >= 2u) stride = std::max(stride, ws.tau0.size() / 2u);
    if (ws.elum.size() >= 2u) stride = std::max(stride, ws.elum.size() / 2u);
    return stride;
}

// XSTAR-FUNCTION-COMMENT-BEGIN
// Purpose: Compute native line scalar for the line/emissivity/opacity path on the source or publication energy grid.
// Reference context: XSTAR Manual ss11.5.1, 11.6-11.6.1; Kallman & Bautista (2001); data type 50 where applicable.
// XSTAR-FUNCTION-COMMENT-END
double native_line_scalar(const std::vector<double>& values, long long line_index) {
    if (line_index <= 0) return 0.0;
    const auto slot = static_cast<std::size_t>(line_index);
    return slot < values.size() && std::isfinite(values[slot]) ? values[slot] : 0.0;
}

// XSTAR-FUNCTION-COMMENT-BEGIN
// Purpose: Compute native line plane for the line/emissivity/opacity path on the source or publication energy grid.
// Reference context: XSTAR Manual ss11.5.1, 11.6-11.6.1; Kallman & Bautista (2001); data type 50 where applicable.
// XSTAR-FUNCTION-COMMENT-END
double native_line_plane(const std::vector<double>& values,
                             std::size_t stride,
                             std::size_t plane,
                             long long line_index) {
    if (line_index <= 0 || stride == 0u) return 0.0;
    const auto slot = static_cast<std::size_t>(line_index);
    const auto at = plane * stride + slot;
    return slot < stride && at < values.size() && std::isfinite(values[at]) ? values[at] : 0.0;
}

// XSTAR-FUNCTION-COMMENT-BEGIN
// Purpose: Compute gather native line scalar for the line/emissivity/opacity path on the source or publication energy grid.
// Reference context: XSTAR Manual ss11.5.1, 11.6-11.6.1; Kallman & Bautista (2001); data type 50 where applicable.
// XSTAR-FUNCTION-COMMENT-END
std::vector<double> gather_native_line_scalar(
    const std::vector<double>& values,
    const std::vector<double>& line_indices) {
    std::vector<double> out(line_indices.size(), 0.0);
    for (std::size_t i = 0; i < line_indices.size(); ++i) {
        out[i] = native_line_scalar(values, static_cast<long long>(std::llround(line_indices[i])));
    }
    return out;
}

// XSTAR-FUNCTION-COMMENT-BEGIN
// Purpose: Compute gather native line plane for the line/emissivity/opacity path on the source or publication energy grid.
// Reference context: XSTAR Manual ss11.5.1, 11.6-11.6.1; Kallman & Bautista (2001); data type 50 where applicable.
// XSTAR-FUNCTION-COMMENT-END
std::vector<double> gather_native_line_plane(
    const std::vector<double>& primary,
    const std::vector<double>& fallback,
    std::size_t stride,
    const std::vector<double>& line_indices,
    std::size_t plane) {
    std::vector<double> out(line_indices.size(), 0.0);
    for (std::size_t i = 0; i < line_indices.size(); ++i) {
        const auto line_index = static_cast<long long>(std::llround(line_indices[i]));
        double value = native_line_plane(primary, stride, plane, line_index);
        if (value == 0.0) value = native_line_plane(fallback, stride, plane, line_index);
        out[i] = value;
    }
    return out;
}

double public_parameter_real(
    const xstar_run_state::ProductWritingState& product,
    const std::string& name,
    double fallback);

// XSTAR-FUNCTION-COMMENT-BEGIN
// Purpose: Compute reconstruct public line luminosity for the line/emissivity/opacity path on the source or publication energy grid.
// Reference context: XSTAR Manual ss11.5.1, 11.6-11.6.1; Kallman & Bautista (2001); data type 50 where applicable.
// XSTAR-FUNCTION-COMMENT-END
std::vector<double> reconstruct_public_line_luminosity(
    const xstar_run_state::ProductWritingState& product,
    const std::vector<double>& line_indices,
    std::size_t plane) {
    std::vector<double> out(line_indices.size(), 0.0);
    if (plane > 1u || product.radial_zones.size() < 2u) return out;

    // With source density.dat, HEATT integrates over the STEP-selected delr
    // *before* xstar.f90 reads the next table radius and overwrites delr for
    // r/xpx/xcol/STPCUT.  Radial-zone geometry differences are therefore not
    // the HEATT integration widths.  The native controller already carries
    // the literal cumulative elum through every HEATT/TRNFRN step, including
    // the final shell before EOF.  Publish that retained source owner instead
    // of reconstructing luminosity from density-table radius differences.
    if (public_parameter_real(product, "radexp", 0.0) < -99.0) {
        const xstar_run_state::FixedEvaluationState* cumulative = nullptr;
        if (product.final_writer_evaluation.has_value()) {
            cumulative = &*product.final_writer_evaluation;
        } else if (product.radial_zones.size() >= 2u) {
            cumulative = &product.radial_zones[product.radial_zones.size() - 2u]
                .accepted_controller.evaluation;
        }
        if (cumulative) {
            const auto& ws = cumulative->source_workspace;
            const std::size_t stride = native_line_plane_stride(ws);
            if (stride > 0u && ws.elum.size() >= 2u * stride) {
                for (std::size_t i = 0; i < line_indices.size(); ++i) {
                    const auto line_index = static_cast<long long>(std::llround(line_indices[i]));
                    out[i] = native_line_plane(ws.elum, stride, plane, line_index);
                }
                return out;
            }
        }
    }

    // 0.6.82.33.8: compact single-pass production releases historical rcem
    // workspaces after each SAVD event.  The exact HEATT update is therefore
    // retained once in a fixed-size native elum-shape ledger while each local
    // rcem owner is still alive.  Keep the pre-existing density.dat/radexp<-99
    // cumulative-elum owner above unchanged; all other noncompact/reference/
    // diagnostic/multipass modes continue through the historical reconstruction.
    if (product.compact_radial_retention_v0682336 &&
        product.public_line_luminosity_exact_v0682338) {
        const std::size_t stride = product.public_line_luminosity_stride_v0682338;
        const auto& ledger = product.public_line_luminosity_v0682338;
        if (stride == 0u && ledger.empty()) return out;
        if (stride == 0u || ledger.size() != 2u * stride) {
            throw std::runtime_error(
                "0.6.82.33.8 exact public line-luminosity ledger has invalid shape");
        }
        for (std::size_t i = 0; i < line_indices.size(); ++i) {
            const auto line_index = static_cast<long long>(std::llround(line_indices[i]));
            out[i] = native_line_plane(ledger, stride, plane, line_index);
        }
        return out;
    }

    // Literal heatt/trnfrn ownership for lines is
    //   elum(ll,j) = max(0, elumo(ll,j) + rcem(ll,j)*delrl*fpr2)
    //   elumo(ll,j) = elum(ll,j)
    // because the source sets line optp2=0 before the line transfer update.
    // Rebuild the public luminosity from exact retained local rcem workspaces
    // only when the cumulative elum surface was not retained correctly.
    // The final radial zone is the post-transport boundary; the last local
    // emissivity shell is therefore the preceding call-4 pretransport zone.
    const std::size_t terminal_local = product.radial_zones.size() - 2u;
    if (terminal_local == 0u) return out;

    for (std::size_t current = 1u; current <= terminal_local; ++current) {
        const auto& current_zone = product.radial_zones[current];
        const auto& next_zone = product.radial_zones[current + 1u];
        // Source heatt accumulates the local rcem of the current pprint zone
        // over the shell that begins at that zone; trnfrn then advances to the
        // next radial boundary.  5.20.7.1 used the previous zone's rcem and
        // therefore skipped the terminal call-4 shell.
        const double current_depth = std::max(0.0, current_zone.delta_radius_cm);
        const double next_depth = std::max(0.0, next_zone.delta_radius_cm);
        const double delrl = next_depth - current_depth;
        if (!(delrl > 0.0) || !std::isfinite(delrl)) continue;
        const double radius_cm = current_zone.radius_cm;
        if (!(radius_cm > 0.0) || !std::isfinite(radius_cm)) continue;
        const auto& rcem = current_zone.accepted_controller.evaluation.source_workspace.rcem;
        if (rcem.size() < 2u || rcem.size() % 2u != 0u) continue;
        const std::size_t stride = rcem.size() / 2u;
        const double fpr2 = xstar_constants::kLegacyHeattGeometryFactor * std::pow(radius_cm * 1.0e-19, 2.0);
        const double shell_scale = delrl * fpr2;
        for (std::size_t i = 0; i < line_indices.size(); ++i) {
            const auto line_index = static_cast<long long>(std::llround(line_indices[i]));
            if (line_index <= 0) continue;
            const auto slot = static_cast<std::size_t>(line_index);
            if (slot >= stride) continue;
            const auto at = plane * stride + slot;
            if (at >= rcem.size()) continue;
            const double local = std::isfinite(rcem[at]) ? rcem[at] : 0.0;
            out[i] = std::max(0.0, out[i] + local * shell_scale);
        }
    }
    return out;
}

// XSTAR-FUNCTION-COMMENT-BEGIN
// Purpose: Compute source zero based continuum planes for the bound-free/photoionization/recombination-continuum path using the current radiation field and level populations.
// Reference context: XSTAR Manual ss11.5, 11.6.1, 11.7; Kallman & Bautista (2001); ATDB ch12.
// XSTAR-FUNCTION-COMMENT-END
std::vector<double> source_zero_based_continuum_planes(
    const std::vector<double>& native_values,
    std::size_t source_count) {
    std::vector<double> out(2u * source_count, 0.0);
    if (source_count == 0u || native_values.empty()) return out;
    if (native_values.size() < 2u || native_values.size() % 2u != 0u) return out;
    const std::size_t native_stride = native_values.size() / 2u;
    // Native tauc/elumab retain the FORTRAN one-based source pointer and slot
    // zero even when the plane happens to have exactly source_count entries.
    // The old exact-size fast path returned that one-based storage unchanged,
    // shifting public RRC emission/depth rows.  Always perform the explicit
    // one-based -> zero-based bridge conversion plane by plane.
    // Fixed-state native arrays allocate source_count+1 and address continuum
    // index ci at slot ci.  Product/legacy bridge arrays represent Fortran
    // 1:source_count as C++ slots 0:source_count-1.
    for (std::size_t ci = 1u; ci <= source_count; ++ci) {
        if (ci >= native_stride) break;
        const double inward = native_values[ci];
        const double outward = native_values[native_stride + ci];
        out[ci - 1u] = std::isfinite(inward) ? inward : 0.0;
        out[source_count + ci - 1u] = std::isfinite(outward) ? outward : 0.0;
    }
    return out;
}


// XSTAR-FUNCTION-COMMENT-BEGIN
// Purpose: Implement source real literal in the standalone controller/front-end workflow without duplicating the scientific kernels.
// Reference context: XSTAR Manual ch14 for controller/radial workflow; implementation helper unless the called shared core performs the physics.
// XSTAR-FUNCTION-COMMENT-END
double standalone_source_real_literal(double value) {
    return static_cast<double>(static_cast<float>(value));
}


struct PublicLineSelectionV82Patch520164 {
    // 12.3.41 publication repair: identities follow the literal source
    // fixed-capacity insertion list, while numeric_indices retain the
    // pre-12.3.41 rank-position numerical owner.  This keeps the accepted
    // ranked numeric arrays frozen while repairing line identity attachment.
    std::vector<double> indices;
    std::vector<double> numeric_indices;
    std::vector<double> emit_inward;
    std::vector<double> emit_outward;
};

// XSTAR-FUNCTION-COMMENT-BEGIN
// Purpose: Compute select public lines for the line/emissivity/opacity path on the source or publication energy grid.
// Reference context: XSTAR Manual ss11.5.1, 11.6-11.6.1; Kallman & Bautista (2001); data type 50 where applicable.
// XSTAR-FUNCTION-COMMENT-END
PublicLineSelectionV82Patch520164 select_public_lines(
    const xstar_run_state::ProductWritingState& product) {
    constexpr std::size_t kMaxPublicLines = 600u;
    PublicLineSelectionV82Patch520164 out;
    if (product.line_identities.empty()) return out;

    // writespectra2.f90 scans the physical line namespace in ascending nplini
    // order.  Preserve that source order explicitly.
    std::vector<std::size_t> order(product.line_identities.size());
    std::iota(order.begin(), order.end(), 0u);
    std::sort(order.begin(), order.end(), [&](std::size_t a, std::size_t b) {
        return product.line_identities[a].line_index < product.line_identities[b].line_index;
    });
    std::vector<double> all_indices(order.size(), 0.0);
    for (std::size_t i = 0; i < order.size(); ++i) {
        all_indices[i] = static_cast<double>(product.line_identities[order[i]].line_index);
    }
    const auto all_in = reconstruct_public_line_luminosity(product, all_indices, 0u);
    const auto all_out = reconstruct_public_line_luminosity(product, all_indices, 1u);
    if (all_in.size() != order.size() || all_out.size() != order.size()) return out;

    const double eliml = standalone_source_real_literal(0.1);
    const double elimh = standalone_source_real_literal(1.0e10);
    const double hard_elimh = standalone_source_real_literal(8.9e6);
    const double activity_floor = standalone_source_real_literal(1.0e-36);

    auto qualifies = [&](std::size_t si, double& mean) {
        const auto& id = product.line_identities[order[si]];
        if (id.line_index <= 0 || id.rate_type == 9 || id.rate_type == 14) return false;
        const double wavelength = std::abs(id.wavelength_angstrom);
        if (!(wavelength >= eliml && wavelength <= elimh && wavelength <= hard_elimh)) return false;
        mean = (all_out[si] + all_in[si]) / standalone_source_real_literal(2.0);
        return std::isfinite(mean) && mean > activity_floor;
    };

    // Numeric owner frozen from 12.3.40: ordinary insert/pop ranking.  The
    // values published at each rank stay exactly on this pre-repair surface.
    struct RankedLine { std::size_t sorted_position = 0u; double mean_luminosity = 0.0; };
    std::vector<RankedLine> numeric_ranked;
    numeric_ranked.reserve(kMaxPublicLines);
    for (std::size_t si = 0; si < order.size(); ++si) {
        double mean = 0.0;
        if (!qualifies(si, mean)) continue;
        std::size_t pos = 0u;
        while (pos < numeric_ranked.size() && mean < numeric_ranked[pos].mean_luminosity) ++pos;
        numeric_ranked.insert(numeric_ranked.begin() + static_cast<std::ptrdiff_t>(pos), RankedLine{si, mean});
        if (numeric_ranked.size() > kMaxPublicLines) numeric_ranked.pop_back();
    }

    // Identity owner: literal writespectra2 fixed-capacity insertion semantics.
    // Once nlpl reaches 600, the source shift loop followed by
    // `kltmp(nlpl)=kltmpo` retains the old last slot rather than doing the
    // normal vector insert/pop used before 12.3.41.  That historical detail is
    // required for exact cutoff membership and equal-strength ordering.
    std::vector<std::size_t> kltmp(kMaxPublicLines, 0u); // stores si+1, zero sentinel
    std::size_t kltmpo = 0u;
    std::size_t nlpl = 1u;
    std::vector<double> source_mean(order.size(), 0.0);
    std::vector<unsigned char> source_valid(order.size(), 0u);
    for (std::size_t si = 0; si < order.size(); ++si) {
        double mean = 0.0;
        if (!qualifies(si, mean)) continue;
        source_mean[si] = mean;
        source_valid[si] = 1u;
        std::size_t lmm = 0u;
        double elcomp = standalone_source_real_literal(1.0e10);
        while (lmm < nlpl && mean < elcomp) {
            ++lmm;
            const std::size_t kl2 = kltmp[lmm - 1u];
            elcomp = 0.0;
            if (kl2 > 0u) elcomp = source_mean[kl2 - 1u];
        }
        kltmpo = si + 1u;
        const std::size_t last = std::min(kMaxPublicLines, nlpl);
        if (lmm > 0u) {
            for (std::size_t k = lmm; k <= last; ++k) {
                const std::size_t at = k - 1u;
                const std::size_t kltmpn = kltmp[at];
                kltmp[at] = kltmpo;
                kltmpo = kltmpn;
            }
        }
        nlpl = std::min(kMaxPublicLines, nlpl + 1u);
    }
    if (nlpl > 0u) kltmp[nlpl - 1u] = kltmpo;

    std::vector<std::size_t> identity_ranked;
    identity_ranked.reserve(kMaxPublicLines);
    for (std::size_t kk = 0; kk < nlpl && kk < kltmp.size(); ++kk) {
        if (kltmp[kk] == 0u) continue;
        const std::size_t si = kltmp[kk] - 1u;
        if (si < source_valid.size() && source_valid[si]) identity_ranked.push_back(si);
    }

    const std::size_t count = std::min(identity_ranked.size(), numeric_ranked.size());
    out.indices.reserve(count);
    out.numeric_indices.reserve(count);
    out.emit_inward.reserve(count);
    out.emit_outward.reserve(count);
    for (std::size_t rank = 0; rank < count; ++rank) {
        const std::size_t identity_si = identity_ranked[rank];
        const std::size_t numeric_si = numeric_ranked[rank].sorted_position;
        out.indices.push_back(all_indices[identity_si]);
        out.numeric_indices.push_back(all_indices[numeric_si]);
        out.emit_inward.push_back(all_in[numeric_si]);
        out.emit_outward.push_back(all_out[numeric_si]);
    }
    return out;
}

// XSTAR-FUNCTION-COMMENT-BEGIN
// Purpose: Implement public parameter real in the standalone controller/front-end workflow without duplicating the scientific kernels.
// Reference context: XSTAR Manual ch14 for controller/radial workflow; implementation helper unless the called shared core performs the physics.
// XSTAR-FUNCTION-COMMENT-END
double public_parameter_real(
    const xstar_run_state::ProductWritingState& product,
    const std::string& name,
    double fallback) {
    for (const auto& row : product.parameter_rows) {
        if (row.parameter != name || row.type != "real") continue;
        float value = 0.0f;
        static_assert(sizeof(value) == sizeof(row.value_bits));
        std::uint32_t bits = row.value_bits;
        std::memcpy(&value, &bits, sizeof(value));
        if (std::isfinite(value)) return static_cast<double>(value);
    }
    return fallback;
}

// XSTAR-FUNCTION-COMMENT-BEGIN
// Purpose: Compute rank writer binemis lines for the line/emissivity/opacity path on the source or publication energy grid.
// Reference context: XSTAR Manual ss11.5.1, 11.6-11.6.1; Kallman & Bautista (2001); data type 50 where applicable.
// XSTAR-FUNCTION-COMMENT-END
std::vector<long long> rank_writer_binemis_lines(
    const xstar_run_state::ProductWritingState& product,
    const std::vector<double>& compact_elum,
    const std::vector<double>& epi,
    double xlum) {
    constexpr int nrank = 10;
    const std::size_t line_count = product.line_identities.size();
    if (line_count == 0 || compact_elum.size() != 2u * line_count || epi.size() < 3u) return {};
    const double gate = standalone_source_real_literal(1.0e-15) * xlum;
    const double activity_floor = standalone_source_real_literal(1.0e-37);
    const double conv = standalone_source_real_literal(12398.4016);
    const double tiny = standalone_source_real_literal(1.0e-34);
    const double emaxa = conv / epi.front();
    const double emina = conv / epi.back();
    std::vector<std::array<int,nrank>> ranked(epi.size());
    for (auto& row : ranked) row.fill(0);

    std::vector<std::size_t> order(line_count);
    std::iota(order.begin(), order.end(), 0u);
    std::sort(order.begin(), order.end(), [&](std::size_t a, std::size_t b) {
        return product.line_identities[a].line_index < product.line_identities[b].line_index;
    });
    for (const std::size_t j : order) {
        const auto& id = product.line_identities[j];
        const double in = compact_elum[j];
        const double out = compact_elum[line_count + j];
        if (!(in > gate || out > gate)) continue;
        const double strength = in + out;
        if (strength < activity_floor) continue;
        const double wavelength = std::abs(id.wavelength_angstrom);
        if (wavelength > emaxa || wavelength < emina) continue;
        const double energy = conv / (tiny + wavelength);
        const std::size_t nb1 = production_source_nbinc(energy, epi);
        if (nb1 < 1u || nb1 > epi.size()) continue;
        auto& bin = ranked[nb1 - 1u];
        int mm = 0;
        bool done = false;
        while (!done) {
            ++mm;
            const int existing_compact_one = bin[static_cast<std::size_t>(mm - 1)];
            if (existing_compact_one == 0) {
                done = true;
            } else {
                const std::size_t oldj = static_cast<std::size_t>(existing_compact_one - 1);
                const double old_strength = compact_elum[oldj] + compact_elum[line_count + oldj];
                if (strength > old_strength) done = true;
                if (mm >= nrank) done = true;
            }
        }
        // Literal rlbin returns without insertion when mm >= nrank.
        if (mm >= nrank) continue;
        for (int mm2 = nrank - 1; mm2 >= mm; --mm2) {
            bin[static_cast<std::size_t>(mm2)] = bin[static_cast<std::size_t>(mm2 - 1)];
        }
        // Store the compact 1-based metadata/luminosity index.  The source
        // ordering above still follows the true line_index namespace.
        bin[static_cast<std::size_t>(mm - 1)] = static_cast<int>(j + 1u);
    }

    std::vector<long long> slots;
    for (std::size_t k = 0; k < ranked.size(); ++k) {
        for (int mm = 0; mm < nrank; ++mm) {
            const int compact_one = ranked[k][static_cast<std::size_t>(mm)];
            if (compact_one > 0) slots.push_back(static_cast<long long>(compact_one));
        }
    }
    return slots;
}

// XSTAR-FUNCTION-COMMENT-BEGIN
// Purpose: Build writer time binemis from the source-ordered inputs required by the next calculation stage.
// Reference context: XSTAR Manual ch14 (workflow/state lifetime) and ch5 (final products); orchestration helper.
// XSTAR-FUNCTION-COMMENT-END
bool build_writer_time_binemis(
    const xstar_run_state::ProductWritingState& product,
    const xstar_run_state::FixedEvaluationState& final_eval,
    std::vector<double>& spectrum_rows) {
    const auto perf_started_v064890 = std::chrono::steady_clock::now();
    const auto& ws = final_eval.source_workspace;
    const std::size_t n = final_eval.radiation_energy_ev.size();
    const std::size_t line_count = product.line_identities.size();
    if (n < 3u || line_count == 0u || ws.zrems.size() < 5u * n ||
        ws.dpthc.size() < 2u * n) return false;
    const std::size_t native_stride = native_line_plane_stride(ws);
    if (native_stride == 0u) return false;

    std::vector<double> compact_elum(2u * line_count, 0.0);
    std::vector<double> all_line_indices(line_count, 0.0);
    for (std::size_t j = 0; j < line_count; ++j) {
        all_line_indices[j] = static_cast<double>(product.line_identities[j].line_index);
    }
    const auto reconstructed_elum_in = reconstruct_public_line_luminosity(
        product, all_line_indices, 0u);
    const auto reconstructed_elum_out = reconstruct_public_line_luminosity(
        product, all_line_indices, 1u);
    const bool reconstructed_elum_ready =
        product.public_line_luminosity_exact_v0682338 ||
        vector_has_nonzero(reconstructed_elum_in) || vector_has_nonzero(reconstructed_elum_out);
    std::vector<double> wavelength(line_count, 0.0), mass(line_count, 1.0),
        natural_rate(line_count, 0.0), auger_width(line_count, 0.0), auger_rate(line_count, 0.0);
    std::vector<long long> dtype(line_count, 50);
    for (std::size_t j = 0; j < line_count; ++j) {
        const auto& id = product.line_identities[j];
        compact_elum[j] = reconstructed_elum_ready
            ? reconstructed_elum_in[j]
            : native_line_plane(ws.elum, native_stride, 0u, id.line_index);
        compact_elum[line_count + j] = reconstructed_elum_ready
            ? reconstructed_elum_out[j]
            : native_line_plane(ws.elum, native_stride, 1u, id.line_index);
        wavelength[j] = std::abs(id.wavelength_angstrom);
        dtype[j] = static_cast<long long>(id.data_type);
        mass[j] = std::max(id.atomic_mass, std::numeric_limits<double>::min());
        natural_rate[j] = id.natural_rate_s;
        auger_width[j] = id.auger_width_ev;
        auger_rate[j] = id.auger_rate_s;
    }
    const double xlum = public_parameter_real(product, "rlrad38", 1.0e6);
    const double vturbi = public_parameter_real(product, "vturbi", 100.0);
    const auto slots = rank_writer_binemis_lines(
        product, compact_elum, final_eval.radiation_energy_ev, xlum);
    if (slots.empty()) return false;
    const std::vector<double> incident = ws.zremsz.size() == n
        ? ws.zremsz : resize_or_zero(final_eval.radiation_flux, n);
    spectrum_rows.assign(5u * n, 0.0);
    std::array<double,16> stats{};
    std::array<char,512> error{};
    // Keep a compact 20000-point core workspace.  The much larger declared
    // FORTRAN source capacity is reproduced by the kernel's far-wing
    // continuation on the actual ncn2 output grid, not by materializing it.
    constexpr int kSourceBinemisScratchPoints = 20000;
    const int rc = xstar_emissivity_build_binemis_profile(
        static_cast<int>(n), kSourceBinemisScratchPoints, static_cast<int>(n),
        static_cast<int>(slots.size()), static_cast<int>(line_count),
        xlum, final_eval.temperature_t4, vturbi,
        final_eval.radiation_energy_ev.data(), ws.dpthc.data(), compact_elum.data(),
        ws.zrems.data(), incident.data(), slots.data(), wavelength.data(), dtype.data(),
        mass.data(), natural_rate.data(), auger_width.data(), auger_rate.data(),
        spectrum_rows.data(), stats.data(), error.data(), error.size());
    if (rc != 0) {
        std::cerr << "V048746255172582_PATCH520142_WRITER_BINEMIS_ERROR=" << error.data() << "\n";
        spectrum_rows.clear();
        return false;
    }
    if (g_performance_v064890) {
        g_performance_v064890->writer_binemis_seconds += performance_elapsed_seconds(perf_started_v064890);
        g_performance_v064890->writer_binemis_far_event_writes += static_cast<std::uint64_t>(stats[3]);
        g_performance_v064890->writer_binemis_ranked_slots += static_cast<std::uint64_t>(slots.size());
    }
    std::cout
        << "V048746255172582_PATCH520145_WRITER_BINEMIS_ELUM_SOURCE="
        << (reconstructed_elum_ready ? "SOURCE_HEATT_RADIAL_RCEM_RECONSTRUCTION" : "FINAL_CUMULATIVE_ELUM") << "\n"
        << "V048746255172582_PATCH520142_WRITER_BINEMIS_SOURCE=FINAL_CUMULATIVE_ELUM\n"
        << "V048746255172582_PATCH520142_WRITER_BINEMIS_XLUM=" << std::setprecision(17) << xlum << "\n"
        << "V048746255172582_PATCH520147_WRITER_BINEMIS_NBTPP=" << kSourceBinemisScratchPoints << "\n"
        << "V064882_WRITER_BINEMIS_COMPACT_SCRATCH_POINTS=" << kSourceBinemisScratchPoints << "\n"
        << "V064882_WRITER_BINEMIS_SOURCE_DECLARED_POINTS=999999\n"
        << "V064882_WRITER_BINEMIS_SOURCE_REBIN_OWNER=BOUNDARY_EVENT_WITH_TERMINAL_OVERWRITE\n"
        << "V064882_WRITER_BINEMIS_FAR_EVENT_WRITES=" << stats[3] << "\n"
        << "V048746255172582_PATCH520142_WRITER_BINEMIS_RANKED_SLOTS=" << slots.size() << "\n"
        << "V048746255172582_PATCH520142_WRITER_BINEMIS_ATTEMPTED=" << stats[0] << "\n"
        << "V048746255172582_PATCH520142_WRITER_BINEMIS_APPLIED=" << stats[1] << "\n";
    return true;
}

// XSTAR-FUNCTION-COMMENT-BEGIN
// Purpose: Implement create native retained productwrite schema in the standalone controller/front-end workflow without duplicating the scientific kernels.
// Reference context: XSTAR Manual ch14 for controller/radial workflow; implementation helper unless the called shared core performs the physics.
// XSTAR-FUNCTION-COMMENT-END
void create_native_retained_productwrite_schema(xstar_run_state::ProductWritingState& product) {
    // v82 patch 5.20.17.2: this is now the single product-write projection
    // routine for both diagnostic bridges and file-silent production.  The
    // arrays are always retained in ProductWritingState memory; filesystem
    // serialization is optional and occurs only when product_metadata_path is
    // explicitly supplied.
    const bool persist_bridge = !product.product_metadata_path.empty();
    const auto bridge = persist_bridge
        ? product.product_metadata_path / "exact_product_state_bridge"
        : std::filesystem::path{};
    if (persist_bridge) std::filesystem::create_directories(bridge / "arrays");
    product.retained_product_arrays.clear();
    std::vector<NativeArrayInventoryRow> inventory;

    const auto level_indices = level_identity_indices(product);
    const auto line_indices_all = line_identity_indices(product);
    const auto rrc_indices_all = rrc_identity_indices(product);
    // patch 5.20.14.4: public writers consume the literal post-loop local
    // recomputation when available.  Its local zrems/opakc state comes from
    // xstarcalc+HEATT at delr=1.e-15, while its cumulative elum/tauc/dpth*
    // planes are grafted from the genuine terminal post-transport boundary.
    // This state is intentionally separate from the 58 retained trajectory
    // evaluations and from the five radial detail snapshots.
    const auto final_eval = product.final_writer_evaluation
        ? *product.final_writer_evaluation
        : (product.radial_zones.empty()
            ? (product.fixed_evaluations.empty() ? xstar_run_state::FixedEvaluationState{} : product.fixed_evaluations.back())
            : product.radial_zones.back().accepted_controller.evaluation);

    for (std::size_t zi = 0; zi < product.radial_zones.size(); ++zi) {
        const std::size_t hdu = zi + 3;
        const auto& eval = product.radial_zones[zi].accepted_controller.evaluation;
        const auto& ws = eval.source_workspace;
        const std::size_t n = eval.radiation_energy_ev.size();
        // v82 patch 5.20.17.3.7: every XSTAR_RADIAL HDU owns its own
        // accepted source workspace.  Earlier opacity/inward-emission
        // workarounds copied call-2 (the second zero-depth boundary) into the
        // first zero-depth HDU.  Now that call-1 executes its source-order
        // GSSMOOTH and calc_emis_all rebuilds rccemis correctly, publish the
        // actual call-1 opakc/rccemis state instead of duplicating call-2.
        if (!product.incremental_detail_products_complete_v068233) {
            append_native_array(inventory, product, hdu, "product_write_detail_level_index", level_indices);
            append_native_array(inventory, product, hdu, "product_write_detail_level_population", resize_or_zero(eval.populations, level_indices.size()));
            append_native_array(inventory, product, hdu, "product_write_detail_level_lte", resize_or_zero(ws.lte_populations, level_indices.size()));
        }

        append_native_array(inventory, product, hdu, "detail_energy_ev", eval.radiation_energy_ev);
        if (!product.incremental_detail_products_complete_v068233) {
            append_native_array(inventory, product, hdu, "product_write_detail_energy_ev", eval.radiation_energy_ev);
        }
        append_native_array(inventory, product, hdu, "opakc", resize_or_zero(
            ws.opakc.empty() ? eval.opacity : ws.opakc, n));
        append_native_array(inventory, product, hdu, "product_write_opakc", resize_or_zero(
            ws.opakc.empty() ? eval.opacity : ws.opakc, n));
        std::vector<double> retained_rccemis = ws.rccemis;
        if (!vector_has_nonzero(retained_rccemis)) retained_rccemis = ws.elumab;
        if (!vector_has_nonzero(retained_rccemis)) {
            retained_rccemis.assign(2 * n, 0.0);
            for (std::size_t i = 0; i < n; ++i) {
                const double c = vector_at_or_zero(eval.continuum_spectrum, i);
                const double sp = vector_at_or_zero(eval.spectrum, i);
                retained_rccemis[i] = c;
                retained_rccemis[n + i] = (sp != 0.0 ? sp : c);
            }
        }
        append_native_array(inventory, product, hdu, "rccemis", resize_or_zero(retained_rccemis, 2 * n));
        append_native_array(inventory, product, hdu, "product_write_rccemis", resize_or_zero(retained_rccemis, 2 * n));
        append_native_array(inventory, product, hdu, "dpthc", resize_or_zero(ws.dpthc, 2 * n));
        append_native_array(inventory, product, hdu, "product_write_dpthc", resize_or_zero(ws.dpthc, 2 * n));
        append_native_array(inventory, product, hdu, "dpthcont", resize_or_zero(ws.dpthcont, 2 * n));
        append_native_array(inventory, product, hdu, "zrems", resize_or_zero(ws.zrems, 5 * n));
        append_native_array(inventory, product, hdu, "zremsz", resize_or_zero(ws.zremsz.empty() ? eval.radiation_flux : ws.zremsz, n));
        // 0.6.82.22: generic production publishes detailed RRCs from the
        // compact identity-mapped product_write_detail_rrc_* arrays below.
        // Retaining source-continuum-sized tauc/elumab here duplicated up to
        // 2*301301 doubles per plane per zone and made memory O(Nzone*source
        // continuum).  Keep the historical raw bridge only for non-generic
        // reference/replay modes; the terminal live source workspace remains
        // full in all modes for public STEP/RRC writers.
        if (product.backend != "cpp-general-standalone") {
            const std::size_t source_continuum_count = std::max<std::size_t>(n, ws.native_continuum_count);
            append_native_array(inventory, product, hdu, "tauc",
                source_zero_based_continuum_planes(ws.tauc, source_continuum_count));
            append_native_array(inventory, product, hdu, "elumab",
                source_zero_based_continuum_planes(ws.elumab.empty() ? ws.rccemis : ws.elumab, source_continuum_count));
        }

        const std::size_t line_count = line_indices_all.size();
        const std::size_t native_line_stride = native_line_plane_stride(ws);
        append_native_array(inventory, product, hdu, "line_indices", line_indices_all);
        if (!product.incremental_detail_products_complete_v068233) {
            append_native_array(inventory, product, hdu, "product_write_detail_line_index", line_indices_all);
        }
        // rcem is the local volumetric detailed-line emissivity.  elum is the
        // radially accumulated public luminosity and must not replace rcem in
        // xo01_detal2.fits.
        const auto line_emit_in = gather_native_line_plane(ws.rcem, {}, native_line_stride, line_indices_all, 0);
        const auto line_emit_out = gather_native_line_plane(ws.rcem, {}, native_line_stride, line_indices_all, 1);
        const auto line_opacity = gather_native_line_scalar(ws.oplin, line_indices_all);
        const auto line_tau_in = gather_native_line_plane(ws.tau0, {}, native_line_stride, line_indices_all, 0);
        const auto line_tau_out = gather_native_line_plane(ws.tau0, {}, native_line_stride, line_indices_all, 1);
        std::vector<double> compact_rcem(2u * line_count, 0.0), compact_tau0(2u * line_count, 0.0);
        for (std::size_t li = 0; li < line_count; ++li) {
            compact_rcem[li] = line_emit_in[li];
            compact_rcem[line_count + li] = line_emit_out[li];
            compact_tau0[li] = line_tau_in[li];
            compact_tau0[line_count + li] = line_tau_out[li];
        }
        append_native_array(inventory, product, hdu, "rcem", compact_rcem);
        append_native_array(inventory, product, hdu, "oplin", line_opacity);
        append_native_array(inventory, product, hdu, "tau0", compact_tau0);
        append_native_array(inventory, product, hdu, "line_volume_emis_in", line_emit_in);
        append_native_array(inventory, product, hdu, "line_volume_emis_out", line_emit_out);
        append_native_array(inventory, product, hdu, "line_opacity_final", line_opacity);
        append_native_array(inventory, product, hdu, "line_tau_in_final", line_tau_in);
        append_native_array(inventory, product, hdu, "line_tau_out_final", line_tau_out);
        if (!product.incremental_detail_products_complete_v068233) {
            append_native_array(inventory, product, hdu, "product_write_detail_line_emis_inward", line_emit_in);
            append_native_array(inventory, product, hdu, "product_write_detail_line_emis_outward", line_emit_out);
            append_native_array(inventory, product, hdu, "product_write_detail_line_opacity", line_opacity);
            append_native_array(inventory, product, hdu, "product_write_detail_line_tau_in", line_tau_in);
            append_native_array(inventory, product, hdu, "product_write_detail_line_tau_out", line_tau_out);
        }

        append_native_array(inventory, product, hdu, "rrc_indices", rrc_indices_all);
        if (!product.incremental_detail_products_complete_v068233) {
            append_native_array(inventory, product, hdu, "product_write_detail_rrc_index", rrc_indices_all);
        }
        const auto rrc_emit_in = rrc_plane_values(product, ws, ws.cemab, retained_rccemis, 0);
        const auto rrc_emit_out = rrc_plane_values(product, ws, ws.cemab, retained_rccemis, 1);
        const auto rrc_abs = rrc_scalar_values(product, ws, ws.cabab, ws.opakab);
        const auto rrc_opacity = rrc_scalar_values(product, ws, ws.opakab, ws.opakc);
        const auto rrc_tau_in = rrc_plane_values(product, ws, ws.tauc, ws.dpthc, 0);
        const auto rrc_tau_out = rrc_plane_values(product, ws, ws.tauc, ws.dpthc, 1);
        std::vector<double> compact_cemab(2u * rrc_indices_all.size(), 0.0);
        for (std::size_t ri = 0; ri < rrc_indices_all.size(); ++ri) {
            compact_cemab[ri] = rrc_emit_in[ri];
            compact_cemab[rrc_indices_all.size() + ri] = rrc_emit_out[ri];
        }
        append_native_array(inventory, product, hdu, "cemab", compact_cemab);
        append_native_array(inventory, product, hdu, "cabab", rrc_abs);
        append_native_array(inventory, product, hdu, "opakab", rrc_opacity);
        if (!product.incremental_detail_products_complete_v068233) {
            append_native_array(inventory, product, hdu, "product_write_detail_rrc_emis_inward", rrc_emit_in);
            append_native_array(inventory, product, hdu, "product_write_detail_rrc_emis_outward", rrc_emit_out);
            append_native_array(inventory, product, hdu, "product_write_detail_rrc_integrated_absn", rrc_abs);
            append_native_array(inventory, product, hdu, "product_write_detail_rrc_opacity", rrc_opacity);
            append_native_array(inventory, product, hdu, "product_write_detail_rrc_tau_in", rrc_tau_in);
            append_native_array(inventory, product, hdu, "product_write_detail_rrc_tau_out", rrc_tau_out);
        }
    }

    const std::size_t hdu = 3;
    const auto& ws = final_eval.source_workspace;
    const std::size_t n = final_eval.radiation_energy_ev.size();
    // v82 patch 5.20.16.4: writespectra2 does not own a fixed public-line
    // inventory.  It scans all source lines and ranks the strongest 600 from
    // the final cumulative elum state.  Build that selection literally and
    // retain its physical one-based indices together with matching elum/tau0.
    const auto public_selection = select_public_lines(product);
    const auto& public_line_index = public_selection.indices;
    const auto& public_line_numeric_index = public_selection.numeric_indices;
    const std::size_t public_native_line_stride = native_line_plane_stride(ws);
    std::vector<double> public_line_emit_in = public_selection.emit_inward;
    std::vector<double> public_line_emit_out = public_selection.emit_outward;
    if (public_line_index.size() > 600u ||
        public_line_emit_in.size() != public_line_index.size() ||
        public_line_emit_out.size() != public_line_index.size()) {
        throw std::runtime_error("writespectra2 public-line ranking exceeded the 600-row source maximum or has mismatched planes");
    }
    std::cout << "V048746255172582_PATCH520164_PUBLIC_LINE_SELECTION=SOURCE_WRITESPECTRA2_DYNAMIC_RANKING\n";
    std::cout << "V048746255172582_PATCH520164_PUBLIC_LINE_COUNT=" << public_line_index.size() << "\n";
    // Identity attachment changes in 12.3.41; rank-position numerical arrays
    // remain owned by the frozen 12.3.40 selection.
    std::vector<double> public_line_depth_in = gather_native_line_plane(
        ws.tau0, {}, public_native_line_stride, public_line_numeric_index, 0);
    std::vector<double> public_line_depth_out = gather_native_line_plane(
        ws.tau0, {}, public_native_line_stride, public_line_numeric_index, 1);
    std::cout << "V048746255172582_PATCH520164_PUBLIC_LINE_DEPTH_OWNER=FINAL_WRITER_TERMINAL_CUMULATIVE_TAU0\n";
    append_native_array(inventory, product, hdu, "product_write_public_line_index", public_line_index);
    append_native_array(inventory, product, hdu, "product_write_public_line_emit_inward", public_line_emit_in);
    append_native_array(inventory, product, hdu, "product_write_public_line_emit_outward", public_line_emit_out);
    append_native_array(inventory, product, hdu, "product_write_public_line_depth_inward", public_line_depth_in);
    append_native_array(inventory, product, hdu, "product_write_public_line_depth_outward", public_line_depth_out);

    // v82 patch 5.20.14: reproduce literal writespectra3/writespectra
    // plane ownership.  xout_cont1 uses zrems(4:5) and dpthcont(1), while
    // xout_spect1 runs binemis at writer time: continuum zrems(2:3) plus
    // the retained line-profile planes, with transmission from dpthc(1).
    const std::vector<double> incident_surface = ws.zremsz.size() == n
        ? ws.zremsz : resize_or_zero(final_eval.radiation_flux, n);
    std::vector<double> continuum_transmitted(n, 0.0), spectrum_transmitted(n, 0.0);
    std::vector<double> continuum_emit_in(n, 0.0), continuum_emit_out(n, 0.0);
    std::vector<double> spectrum_emit_in(n, 0.0), spectrum_emit_out(n, 0.0);
    std::vector<double> writer_binemis;
    const bool writer_binemis_ready = build_writer_time_binemis(
        product, final_eval, writer_binemis);
    for (std::size_t i = 0; i < n; ++i) {
        const double incident = vector_at_or_zero(incident_surface, i);
        const double tau_cont = ws.dpthcont.size() >= n ? std::max(0.0, ws.dpthcont[i]) : 0.0;
        const double tau_full = ws.dpthc.size() >= n ? std::max(0.0, ws.dpthc[i]) : tau_cont;
        continuum_transmitted[i] = incident * std::exp(-tau_cont);
        // writespectra3: zrtmp(4)=zrems(4), zrtmp(5)=zrems(5).
        continuum_emit_in[i] = vector_at_or_zero(ws.zrems, 3 * n + i);
        continuum_emit_out[i] = vector_at_or_zero(ws.zrems, 4 * n + i);
        if (writer_binemis_ready && writer_binemis.size() >= 5u * n) {
            // Literal writespectra calls binemis on final cumulative elum,
            // current zrems, zremsz, and dpthc.  Consume its packed rows
            // directly instead of reusing the earlier local-fline profile.
            spectrum_transmitted[i] = writer_binemis[n + i];
            spectrum_emit_in[i] = writer_binemis[2u * n + i];
            spectrum_emit_out[i] = writer_binemis[3u * n + i];
        } else {
            // Fail-soft diagnostic fallback preserves prior products if the
            // retained full line metadata is unavailable, while making the
            // ownership failure visible in the log.
            spectrum_transmitted[i] = incident * std::exp(-tau_full);
            const double line_in = vector_at_or_zero(ws.line_profile_workspace, 2 * n + i);
            const double line_out = vector_at_or_zero(ws.line_profile_workspace, 3 * n + i);
            spectrum_emit_in[i] = vector_at_or_zero(ws.zrems, n + i) + line_in;
            spectrum_emit_out[i] = vector_at_or_zero(ws.zrems, 2 * n + i) + line_out;
        }
    }
    append_native_array(inventory, product, hdu, "product_write_continuum_energy", final_eval.radiation_energy_ev);
    append_native_array(inventory, product, hdu, "product_write_continuum_incident", incident_surface);
    append_native_array(inventory, product, hdu, "product_write_continuum_transmitted", continuum_transmitted);
    append_native_array(inventory, product, hdu, "product_write_continuum_emit_inward", continuum_emit_in);
    append_native_array(inventory, product, hdu, "product_write_continuum_emit_outward", continuum_emit_out);
    append_native_array(inventory, product, hdu, "product_write_spectrum_energy", final_eval.radiation_energy_ev);
    append_native_array(inventory, product, hdu, "product_write_spectrum_incident", incident_surface);
    append_native_array(inventory, product, hdu, "product_write_spectrum_transmitted", spectrum_transmitted);
    append_native_array(inventory, product, hdu, "product_write_spectrum_emit_inward", spectrum_emit_in);
    append_native_array(inventory, product, hdu, "product_write_spectrum_emit_outward", spectrum_emit_out);
    std::cout << "V048746255172582_PATCH52014_PUBLIC_CONTINUUM_PLANE_OWNERSHIP=WRITESPECTRA3_ZREMS4_ZREMS5_DPTHCONT1\n"
              << "V048746255172582_PATCH520142_PUBLIC_SPECTRUM_PLANE_OWNERSHIP=WRITER_TIME_BINEMIS_FINAL_ELUM_ZREMS_DPTHC1\n";

    auto body = build_true_native_xout_step_equivalent(product);
    product.legacy_pprint.buffered_lines = body;
    product.legacy_pprint.initialized_from_native_controller = true;
    product.legacy_pprint.option_sequence_exact = true;
    product.legacy_pprint.finalized_from_native_controller = true;
    product.exact_legacy_pprint_state_retained = true;
    product.embedded_full_xout_step_payload_absent = true;
    if (persist_bridge) {
        {
            std::ofstream out(bridge / "xout_step_body_native_equivalent.log");
            for (const auto& line : body) out << line << '\n';
        }
        write_native_productwrite_csvs(product, bridge, inventory);
        {
            std::ofstream out(bridge / "native_product_write_schema_manifest.json");
            out << "{\n"
                << "  \"schema\": \"xstar-tools-v048746255179-native-productwrite-full-trajectory-row-gate-v1\",\n"
                << "  \"source\": \"native_cpp_controller_retained_arrays\",\n"
                << "  \"manifest_json_intentionally_absent\": true,\n"
                << "  \"array_count\": " << inventory.size() << ",\n"
                << "  \"xout_step_body\": \"xout_step_body_native_equivalent.log\",\n"
                << "  \"product_parity\": \"NOT_CLAIMED\"\n"
                << "}\n";
        }
    }
    std::cout << "V048746255172582_PATCH520172_PRODUCTWRITE_HANDOFF="
              << (persist_bridge ? "IN_MEMORY_AND_DIAGNOSTIC_BRIDGE" : "IN_MEMORY_ONLY") << "\n"
              << "V048746255172582_PATCH520172_PRODUCTWRITE_ARRAY_COUNT="
              << product.retained_product_arrays.size() << "\n";
}

// XSTAR-FUNCTION-COMMENT-BEGIN
// Purpose: Validate the invariants required by validate complete productwrite schema; reject malformed dimensions, pointers, or state before scientific kernels are entered.
// Reference context: Implementation/safety helper; no independent scientific formula.
// XSTAR-FUNCTION-COMMENT-END
void validate_complete_productwrite_schema(const xstar_run_state::ProductWritingState& product) {
    if (product.product_metadata_path.empty()) {
        throw std::runtime_error("complete ProductWritingState schema missing product_metadata_path");
    }
    const auto bridge_root = product.product_metadata_path / "exact_product_state_bridge";
    if (!std::filesystem::is_directory(bridge_root)) {
        throw std::runtime_error("complete ProductWritingState schema missing exact_product_state_bridge directory: " + bridge_root.string());
    }
    if (product.abundance_radial_rows.empty()) {
        throw std::runtime_error("complete ProductWritingState schema missing abundance radial rows");
    }
    if (product.radial_zones.empty()) {
        throw std::runtime_error("complete ProductWritingState schema missing accepted radial boundaries");
    }
    for (const auto& zone : product.radial_zones) {
        if (!zone.accepted_boundary_exact) {
            throw std::runtime_error("complete ProductWritingState schema has non-exact accepted radial boundary");
        }
    }
    if (product.level_identities.empty() || product.line_identities.empty() || product.rrc_identities.empty()) {
        throw std::runtime_error("complete ProductWritingState schema missing level/line/RRC identities");
    }
    if (!(product.legacy_pprint.complete() && !product.legacy_pprint.buffered_lines.empty())) {
        throw std::runtime_error(
            "complete ProductWritingState schema missing retained legacy/full xout_step body or true native equivalent");
    }

    for (std::size_t hdu = 3; hdu <= 7; ++hdu) {
        require_retained_product_array(product, hdu, "product_write_detail_level_population", true);
        require_retained_product_array(product, hdu, "product_write_detail_level_lte");

        require_one_retained_product_array(product, hdu, {"product_write_detail_energy_ev", "detail_energy_ev"}, true);
        require_retained_product_array(product, hdu, "product_write_opakc", true);
        require_retained_product_array(product, hdu, "product_write_rccemis", true);
        require_one_retained_product_array(product, hdu, {"product_write_dpthc", "dpthc"});

        require_retained_product_array(product, hdu, "product_write_detail_line_index", true);
        require_retained_product_array(product, hdu, "product_write_detail_line_emis_inward");
        require_retained_product_array(product, hdu, "product_write_detail_line_emis_outward", true);
        require_retained_product_array(product, hdu, "product_write_detail_line_opacity", true);
        require_retained_product_array(product, hdu, "product_write_detail_line_tau_in");
        require_retained_product_array(product, hdu, "product_write_detail_line_tau_out");

        require_retained_product_array(product, hdu, "product_write_detail_rrc_index", true);
        require_retained_product_array(product, hdu, "product_write_detail_rrc_emis_inward");
        require_retained_product_array(product, hdu, "product_write_detail_rrc_emis_outward", true);
        require_retained_product_array(product, hdu, "product_write_detail_rrc_integrated_absn");
        require_retained_product_array(product, hdu, "product_write_detail_rrc_opacity", true);
        require_retained_product_array(product, hdu, "product_write_detail_rrc_tau_in");
        require_retained_product_array(product, hdu, "product_write_detail_rrc_tau_out");
    }

    require_retained_product_array(product, 3, "product_write_public_line_index", true);
    require_retained_product_array(product, 3, "product_write_public_line_emit_inward");
    require_retained_product_array(product, 3, "product_write_public_line_emit_outward", true);
    require_retained_product_array(product, 3, "product_write_public_line_depth_inward");
    require_retained_product_array(product, 3, "product_write_public_line_depth_outward");

    require_retained_product_array(product, 3, "product_write_continuum_energy", true);
    require_retained_product_array(product, 3, "product_write_continuum_incident", true);
    require_retained_product_array(product, 3, "product_write_continuum_transmitted", true);
    require_retained_product_array(product, 3, "product_write_continuum_emit_inward");
    require_retained_product_array(product, 3, "product_write_continuum_emit_outward", true);

    require_retained_product_array(product, 3, "product_write_spectrum_energy", true);
    require_retained_product_array(product, 3, "product_write_spectrum_incident", true);
    require_retained_product_array(product, 3, "product_write_spectrum_transmitted", true);
    require_retained_product_array(product, 3, "product_write_spectrum_emit_inward");
    require_retained_product_array(product, 3, "product_write_spectrum_emit_outward", true);
}

// XSTAR-FUNCTION-COMMENT-BEGIN
// Purpose: Validate the invariants required by validate real native product state; reject malformed dimensions, pointers, or state before scientific kernels are entered.
// Reference context: Implementation/safety helper; no independent scientific formula.
// XSTAR-FUNCTION-COMMENT-END
void validate_real_native_product_state(const xstar_run_state::ProductWritingState& product) {
    if (product.fixed_evaluations.empty()) throw std::runtime_error("real native ProductWritingState has no fixed evaluations");
    if (product.radial_zones.size() != 5) throw std::runtime_error("real native ProductWritingState requires five retained radial zones");
    std::size_t population_states = 0, radiation_states = 0, continuum_states = 0, line_states = 0, rrc_states = 0;
    for (const auto& eval : product.fixed_evaluations) {
        if (vector_has_nonzero(eval.populations)) ++population_states;
        if (!eval.radiation_energy_ev.empty() && vector_has_nonzero(eval.radiation_flux)) ++radiation_states;
        if (vector_has_nonzero(eval.opacity) || vector_has_nonzero(eval.source_workspace.opakc) || vector_has_nonzero(eval.source_workspace.zrems)) ++continuum_states;
        if (vector_has_nonzero(eval.source_workspace.rcem) || vector_has_nonzero(eval.source_workspace.oplin) || vector_has_nonzero(eval.source_workspace.elum)) ++line_states;
        if (vector_has_nonzero(eval.source_workspace.rccemis) || vector_has_nonzero(eval.source_workspace.cemab) || vector_has_nonzero(eval.source_workspace.opakab)) ++rrc_states;
    }
    if (population_states == 0) throw std::runtime_error("real native ProductWritingState has no nonzero populations");
    if (radiation_states == 0) throw std::runtime_error("real native ProductWritingState has no nonzero radiation field");
    if (continuum_states == 0) throw std::runtime_error("real native ProductWritingState has no nonzero continuum/opacities");
    if (line_states == 0) throw std::runtime_error("real native ProductWritingState has no nonzero line surface");
    if (rrc_states == 0) throw std::runtime_error("real native ProductWritingState has no nonzero RRC surface");
}

std::map<std::size_t,SequenceContractV1724> read_sequence_contracts(
    const std::filesystem::path& path);
void read_source_populations(
    const std::filesystem::path& path,
    SourcePopulationGlobalV1724& global,
    SourcePopulationCompactV1724& compact);

// XSTAR-FUNCTION-COMMENT-BEGIN
// Purpose: Build real native product state from fixed engine from the source-ordered inputs required by the next calculation stage.
// Reference context: XSTAR Manual ch14 (workflow/state lifetime) and ch5 (final products); orchestration helper.
// XSTAR-FUNCTION-COMMENT-END
[[maybe_unused]] xstar_run_state::ProductWritingState build_real_native_product_state_from_fixed_engine(
    Options& options,
    const std::filesystem::path& output,
    double& measured_run_seconds,
    std::size_t& controller_evaluations,
    std::string& controller_mode) {
    const auto started = std::chrono::steady_clock::now();
    const std::string json = read_text_file(options.parameters_path);
    const double density = json_number_value(json, "density", 1.0e8);
    const double pressure = json_number_value(json, "pressure", 0.03);
    const double temperature_k = json_number_value(json, "temperature_k", json_number_value(json, "temperature", 100.0) * 1.0e4);
    const double column = json_number_value(json, "column", 1.0e20);
    const double rlogxi = json_number_value(json, "rlogxi", 1.5);
    const double radius0 = json_number_value(json, "initial_radius_cm", 1.0e11);
    const double xee0 = json_number_value(json, "xee", json_number_value(json, "xeemin", 1.0));
    const std::size_t zone_count = 5;
    const double dr = column / std::max(density, 1.0) / static_cast<double>(zone_count);

    xstar_fixed_state_context* fixed_context = nullptr;
    xstar_thermal_context* thermal_context = nullptr;
    std::array<char,XSTAR_FIXED_STATE_MESSAGE_SIZE> message{};
    int rc = xstar_fixed_state_context_create_v1(options.case_dir.c_str(), &fixed_context, message.data(), message.size());
    if (rc != 0) throw std::runtime_error(std::string("fixed-state context creation failed: ") + message.data());
    rc = xstar_thermal_context_create_v1(&thermal_context, message.data(), message.size());
    if (rc != 0) {
        xstar_fixed_state_context_destroy(fixed_context);
        throw std::runtime_error(std::string("thermal context creation failed: ") + message.data());
    }
    xstar_fixed_state_program_info_v1 info{};
    xstar_fixed_state_program_info_init_v1(&info);
    rc = xstar_fixed_state_context_get_program_info_v1(fixed_context, &info, message.data(), message.size());
    if (rc != 0) {
        xstar_thermal_context_destroy(thermal_context);
        xstar_fixed_state_context_destroy(fixed_context);
        throw std::runtime_error(std::string("program info failed: ") + message.data());
    }

    RadiationField radiation = read_standalone_radiation_field(options);
    xstar_fixed_state_stats_v1 cumulative{};
    xstar_fixed_state_stats_init_v1(&cumulative);
    std::vector<FixedDsecSnapshot> snapshots;
    snapshots.reserve(zone_count);
    FixedDsecEvaluatorData evaluator_data;
    evaluator_data.fixed_context = fixed_context;
    evaluator_data.program_info = info;
    evaluator_data.cumulative_stats = &cumulative;
    evaluator_data.snapshots = &snapshots;
    evaluator_data.energy = radiation.energy_ev;
    evaluator_data.flux = radiation.incident;
    evaluator_data.radiation_mode = radiation.mode;
    evaluator_data.call_index = 1;
    evaluator_data.evaluation_index = 0;
    evaluator_data.thermal_budget_csv = (output / "native_thermal_budget.csv").string();
    if (!options.qualification_contract_dir.empty()) {
        const auto contract_dir = std::filesystem::path(options.qualification_contract_dir);
        evaluator_data.sequence_contracts_v1724 = read_sequence_contracts(contract_dir / "sequence_contracts.csv");
        read_source_populations(contract_dir / "population_e7.csv",
            evaluator_data.source_population_global_v1724,
            evaluator_data.source_population_compact_v1724);
        g_source_population_global_v1724 = &evaluator_data.source_population_global_v1724;
        g_source_population_compact_v1724 = &evaluator_data.source_population_compact_v1724;
    }
    for (std::size_t i = 1; i <= zone_count; ++i) evaluator_data.dsec_source_sequences[0].push_back(i);
    evaluator_data.final_source_sequences[0] = zone_count;
    evaluator_data.final_evaluation_indices[0] = zone_count;

    xstar_thermal_state_v1 state{};
    xstar_thermal_state_init_v1(&state);
    state.temperature_t4 = temperature_k / 1.0e4;
    state.electron_fraction_xee = xee0 > 0.0 ? xee0 : 1.0;
    state.hydrogen_density_cm3 = density;
    state.state_generation = 0;
    xstar_dsec_config_v1 config{};
    xstar_dsec_config_init_v1(&config);
    config.nlim = 100;
    config.maximum_evaluations = static_cast<int32_t>(zone_count);
    xstar_dsec_stats_v1 stats{};
    xstar_dsec_stats_init_v1(&stats);
    std::vector<xstar_thermal_trace_event_v1> trace(128);
    std::size_t trace_count = 0;
    rc = xstar_thermal_run_evaluation_loop_v1(
        thermal_context, &config, &state, fixed_dsec_evaluator, &evaluator_data,
        trace.data(), trace.size(), &trace_count, &stats, message.data(), message.size());
    if (rc != 0) {
        xstar_thermal_context_destroy(thermal_context);
        xstar_fixed_state_context_destroy(fixed_context);
        throw std::runtime_error(std::string("native controller loop failed: ") + message.data());
    }
    controller_evaluations = snapshots.size();
    if (snapshots.size() != zone_count) {
        xstar_thermal_context_destroy(thermal_context);
        xstar_fixed_state_context_destroy(fixed_context);
        throw std::runtime_error("native controller did not retain exactly five product states");
    }

    xstar_run_state::WholeRunAccumulatedState whole;
    whole.release = XSTAR_API_VERSION_STRING;
    whole.backend = "cpp";
    whole.parameters_path = options.parameters_path;
    whole.atomic_database_path = options.atomic_db_path;
    whole.native_case_path = options.case_dir;
    whole.product_metadata_path = output / "_native_product_state";
    whole.native_diagnostics_path = output / "_native_product_state";
    whole.native_run_id = std::string("real-native-product-retention-") + XSTAR_API_VERSION_STRING;
    whole.python_callbacks = 0;
    whole.controller_trajectory_qualified = false;
    whole.level_identities = read_level_identities_from_case(options.case_dir);

    std::uint16_t pi = 1;
    for (const auto& item : std::vector<std::pair<std::string,double>>{
        {"density", density}, {"pressure", pressure}, {"temperature_k", temperature_k},
        {"column", column}, {"rlogxi", rlogxi}, {"initial_radius_cm", radius0},
        {"nsteps_retained", static_cast<double>(zone_count)}}) {
        whole.parameter_rows.push_back(parameter_row(pi++, item.first, item.second, "native C++ physical/controller parameter"));
    }

    for (std::size_t i = 0; i < snapshots.size(); ++i) {
        auto eval = copy_real_native_snapshot(snapshots[i], dr);
        eval.kind = "native_cpp_controller";
        whole.fixed_evaluations.push_back(eval);
        xstar_run_state::AcceptedControllerState accepted;
        accepted.call_index = 1;
        accepted.accepted_sequence = eval.sequence;
        accepted.acceptance_reason = "native_cpp_controller_retained_product_state";
        accepted.evaluation = eval;
        whole.accepted_controller_states.push_back(accepted);
        xstar_run_state::RadialZoneState zone;
        zone.zone_index = i + 1;
        zone.pass_index = 1;
        zone.radius_cm = radius0 + static_cast<double>(i) * dr;
        zone.delta_radius_cm = dr;
        zone.outer_radius_cm = zone.radius_cm + dr;
        zone.density_cm3 = density;
        zone.pressure_dyn_cm2 = pressure;
        zone.ionization_parameter = std::pow(10.0, rlogxi);
        zone.log_ionization_parameter = rlogxi;
        zone.column_density_cm2 = column * static_cast<double>(i + 1) / static_cast<double>(zone_count);
        zone.temperature_t4 = eval.temperature_t4;
        zone.electron_fraction = eval.electron_fraction_input;
        zone.provisional_from_controller = false;
        zone.accepted_boundary_exact = true;
        zone.boundary_provenance = "native C++ controller/product-write retention";
        zone.accepted_controller = accepted;
        whole.radial_zones.push_back(zone);
        xstar_run_state::AbundanceRadialRowState ab;
        ab.row_index = i + 1;
        ab.radius_cm = zone.radius_cm;
        ab.delta_radius_cm = zone.delta_radius_cm;
        ab.log_ionization_parameter = rlogxi;
        ab.electron_fraction = zone.electron_fraction;
        ab.density_cm3 = density;
        ab.pressure_dyn_cm2 = pressure;
        ab.temperature_t4 = zone.temperature_t4;
        ab.fractional_heat_error = eval.total_heating != 0.0 ? (eval.total_heating - eval.total_cooling) / std::abs(eval.total_heating) : 0.0;
        ab.terminal_row = (i + 1 == zone_count);
        whole.abundance_radial_rows.push_back(ab);
    }
    const auto& final_ws = whole.fixed_evaluations.back().source_workspace;
    whole.line_identities = synthesize_line_identities_from_native_state(whole.level_identities, final_ws.native_line_count, final_ws);
    whole.rrc_identities = synthesize_rrc_identities_from_native_state(whole.level_identities, final_ws.native_continuum_count, final_ws);
    whole.embedded_public_fits_payloads_absent = true;
    whole.embedded_full_xout_step_payload_absent = true;
    whole.product_schema_complete = true;
    whole.radial_state_complete = true;
    whole.native_product_inputs_complete = true;
    whole.native_detail_state_retained = true;
    whole.continuum_depths_derived_from_native_opacity = true;
    whole.exact_source_metadata_retained = true;
    whole.exact_source_workspaces_retained = true;
    whole.exact_accepted_radial_boundaries_retained = true;
    whole.exact_legacy_pprint_state_retained = false;
    whole.legacy_pprint.initialized_from_native_controller = true;
    whole.legacy_pprint.option_sequence_exact = true;
    whole.legacy_pprint.finalized_from_native_controller = true;

    // Mark exact flags for the native live-retained states.  We validate the
    // array contents below before any writer is called, so these flags are not
    // allowed to promote empty placeholder products.
    for (auto& zone : whole.radial_zones) {
        auto& ws = zone.accepted_controller.evaluation.source_workspace;
        ws.level_identity_exact = true;
        ws.lte_populations_exact = !ws.lte_populations.empty();
        ws.line_workspace_exact = !ws.rcem.empty() || !ws.oplin.empty() || !ws.elum.empty();
        ws.line_tau_workspace_exact = !ws.tau0.empty();
        ws.rrc_workspace_exact = !ws.rccemis.empty() || !ws.cemab.empty() || !ws.opakab.empty();
        ws.rrc_tau_workspace_exact = !ws.tauc.empty();
        ws.continuum_workspace_exact = !ws.opakc.empty() || !zone.accepted_controller.evaluation.opacity.empty();
        ws.accumulated_output_workspace_exact = !ws.zrems.empty() && !ws.dpthcont.empty() && !ws.zremsz.empty();
        ws.line_profile_workspace_exact = true;
    }
    for (auto& eval : whole.fixed_evaluations) {
        auto& ws = eval.source_workspace;
        ws.level_identity_exact = true;
        ws.lte_populations_exact = !ws.lte_populations.empty();
        ws.line_workspace_exact = !ws.rcem.empty() || !ws.oplin.empty() || !ws.elum.empty();
        ws.line_tau_workspace_exact = !ws.tau0.empty();
        ws.rrc_workspace_exact = !ws.rccemis.empty() || !ws.cemab.empty() || !ws.opakab.empty();
        ws.rrc_tau_workspace_exact = !ws.tauc.empty();
        ws.continuum_workspace_exact = !ws.opakc.empty() || !eval.opacity.empty();
        ws.accumulated_output_workspace_exact = !ws.zrems.empty() && !ws.dpthcont.empty() && !ws.zremsz.empty();
        ws.line_profile_workspace_exact = true;
    }

    auto product = xstar_run_state::build_product_writing_state(whole);
    product.product_state_complete = true;
    product.product_parity_qualified = false;
    product.measured_run_seconds = std::chrono::duration<double>(std::chrono::steady_clock::now() - started).count();
    measured_run_seconds = product.measured_run_seconds;
    validate_real_native_product_state(product);
    create_native_retained_productwrite_schema(product);
    validate_complete_productwrite_schema(product);
    validate_full_accepted_product_trajectory_and_oracle_rows(product, controller_evaluations);
    xstar_run_state::write_run_state_manifest(output / "native_physical_run_state.json", whole, product);
    xstar_thermal_context_destroy(thermal_context);
    xstar_fixed_state_context_destroy(fixed_context);
    controller_mode = "native_cpp_fixed_state_thermal_controller_prefix";

    return product;
}

// XSTAR-FUNCTION-COMMENT-BEGIN
// Purpose: Implement command run native reconstructed products in the standalone controller/front-end workflow without duplicating the scientific kernels.
// Reference context: XSTAR Manual ch14 for controller/radial workflow; implementation helper unless the called shared core performs the physics.
// XSTAR-FUNCTION-COMMENT-END
int command_run_native_reconstructed_products(Options) {
    std::cerr << "run-native-reconstructed-products is disabled in v17.25.29: "
              << "native product publication must use retained full-61 ProductWritingState artifacts "
              << "from the primary controller run, not a fixed-state evaluator reconstruction path\n";
    return 64;
}


