extern "C" int32_t xstar_production_zone_abi_version_v0648110(void) {
    return XSTAR_PRODUCTION_ZONE_ABI_V0648110;
}

extern "C" const char* xstar_production_zone_backend_name_v0648110(void) {
    return "xstar_shared_standalone_production_zone_v0648110";
}

extern "C" int32_t xstar_production_zone_run_all_v0648110(
    const char* parameters_path,
    const char* output_dir,
    const char* executable_path,
    char* message,
    std::size_t message_size) {
    auto set_message = [&](const std::string& text) {
        if (!message || message_size == 0) return;
        const std::size_t n = std::min<std::size_t>(message_size - 1u, text.size());
        std::memcpy(message, text.data(), n);
        message[n] = '\0';
    };
    try {
        if (!parameters_path || !*parameters_path || !output_dir || !*output_dir) {
            set_message("parameters_path and output_dir are required");
            return 64;
        }
        Options options;
        options.command = "run-production";
        options.parameters_path = parameters_path;
        options.output_dir = output_dir;
        options.artifact_profile = "none";
        options.artifact_profile_explicit = true;
        const std::filesystem::path executable =
            (executable_path && *executable_path) ? std::filesystem::path(executable_path) : std::filesystem::path();
        ::setenv("XSTAR_V0648110_SHARED_ZONE_MODE", "1", 1);
        const int rc = command_run_standalone_production(options, executable);
        ::unsetenv("XSTAR_V0648110_SHARED_ZONE_MODE");
        set_message(rc == 0 ? "ACCEPT" : ("standalone production returned " + std::to_string(rc)));
        return rc;
    } catch (const std::exception& exc) {
        ::unsetenv("XSTAR_V0648110_SHARED_ZONE_MODE");
        set_message(exc.what());
        return 20;
    } catch (...) {
        ::unsetenv("XSTAR_V0648110_SHARED_ZONE_MODE");
        set_message("unknown shared production-zone exception");
        return 20;
    }
}

extern "C" int32_t xstar_production_zone_context_create_v0648110(
    const char* parameters_path,
    const char* output_dir,
    const char* executable_path,
    void** out_context,
    char* message,
    std::size_t message_size) {
    auto set_message = [&](const std::string& text) {
        if (!message || message_size == 0) return;
        const std::size_t n = std::min<std::size_t>(message_size - 1u, text.size());
        std::memcpy(message, text.data(), n);
        message[n] = '\0';
    };
    if (!out_context) { set_message("out_context is required"); return 64; }
    *out_context = nullptr;
    if (!parameters_path || !*parameters_path || !output_dir || !*output_dir) {
        set_message("parameters_path and output_dir are required");
        return 64;
    }
    try {
        auto* session = new ProductionZoneSessionV0648110();
        session->parameters_path = parameters_path;
        session->output_dir = output_dir;
        session->executable_path = executable_path ? executable_path : "";
        session->worker = std::thread([session] {
            g_production_zone_session_v0648110 = session;
            try {
                Options options;
                options.command = "run-production";
                options.parameters_path = session->parameters_path;
                options.output_dir = session->output_dir;
                options.artifact_profile = "none";
                options.artifact_profile_explicit = true;
                const std::filesystem::path executable = session->executable_path.empty()
                    ? std::filesystem::path() : std::filesystem::path(session->executable_path);
                ::setenv("XSTAR_V0648110_SHARED_ZONE_MODE", "1", 1);
                const int rc = command_run_standalone_production(options, executable);
                ::unsetenv("XSTAR_V0648110_SHARED_ZONE_MODE");
                {
                    std::lock_guard<std::mutex> lock(session->mutex);
                    session->rc = rc;
                    session->finished = true;
                    if (rc != 0) session->error = "standalone production returned " + std::to_string(rc);
                }
            } catch (const std::exception& exc) {
                ::unsetenv("XSTAR_V0648110_SHARED_ZONE_MODE");
                std::lock_guard<std::mutex> lock(session->mutex);
                session->rc = 20;
                session->error = exc.what();
                session->finished = true;
            } catch (...) {
                ::unsetenv("XSTAR_V0648110_SHARED_ZONE_MODE");
                std::lock_guard<std::mutex> lock(session->mutex);
                session->rc = 20;
                session->error = "unknown cpp-zone worker exception";
                session->finished = true;
            }
            g_production_zone_session_v0648110 = nullptr;
            session->cv.notify_all();
        });
        *out_context = session;
        set_message("ACCEPT");
        return 0;
    } catch (const std::exception& exc) {
        set_message(exc.what());
        return 20;
    }
}

extern "C" int32_t xstar_production_zone_context_run_next_zone_v0648110(
    void* context,
    xstar_production_zone_result_v0648110* out_result,
    char* message,
    std::size_t message_size) {
    auto set_message = [&](const std::string& text) {
        if (!message || message_size == 0) return;
        const std::size_t n = std::min<std::size_t>(message_size - 1u, text.size());
        std::memcpy(message, text.data(), n);
        message[n] = '\0';
    };
    auto* session = static_cast<ProductionZoneSessionV0648110*>(context);
    if (!session || !out_result) { set_message("valid context and result are required"); return 64; }
    std::unique_lock<std::mutex> lock(session->mutex);
    if (session->zone_loop_done) {
        set_message("radial zone loop is already complete");
        return 66;
    }
    const std::size_t requested = session->completed_zone + 1u;
    session->allowed_zone = requested;
    session->cv.notify_all();
    session->cv.wait(lock, [&] {
        return session->completed_zone >= requested || session->finished;
    });
    if (session->completed_zone < requested) {
        set_message(session->error.empty() ? "cpp-zone worker stopped before next zone" : session->error);
        return session->rc ? session->rc : 20;
    }
    const auto& r = session->results[requested - 1u];
    out_result->zone_index = static_cast<int32_t>(r.zone_index);
    out_result->dsec_evaluations = static_cast<int32_t>(r.dsec_evaluations);
    out_result->source_sequence = static_cast<int32_t>(r.source_sequence);
    out_result->done_after_zone = r.done_after_zone ? 1 : 0;
    out_result->seconds = r.seconds;
    out_result->temperature_t4 = r.temperature_t4;
    out_result->electron_fraction = r.electron_fraction;
    out_result->hmctot = r.hmctot;
    out_result->heating_minus_cooling_percent = r.heating_minus_cooling_percent;
    set_message("ACCEPT");
    return 0;
}

extern "C" int32_t xstar_production_zone_context_done_v0648110(
    void* context,
    int32_t* out_done,
    int32_t* out_completed_zones,
    char* message,
    std::size_t message_size) {
    auto set_message = [&](const std::string& text) {
        if (!message || message_size == 0) return;
        const std::size_t n = std::min<std::size_t>(message_size - 1u, text.size());
        std::memcpy(message, text.data(), n);
        message[n] = '\0';
    };
    auto* session = static_cast<ProductionZoneSessionV0648110*>(context);
    if (!session || !out_done || !out_completed_zones) {
        set_message("context and done outputs are required"); return 64;
    }
    std::lock_guard<std::mutex> lock(session->mutex);
    *out_done = session->zone_loop_done ? 1 : 0;
    *out_completed_zones = static_cast<int32_t>(session->completed_zone);
    if (session->finished && session->rc != 0) {
        set_message(session->error.empty() ? "cpp-zone worker failed" : session->error);
        return session->rc;
    }
    set_message("ACCEPT");
    return 0;
}

extern "C" int32_t xstar_production_zone_context_finalize_v0648110(
    void* context,
    char* message,
    std::size_t message_size) {
    auto set_message = [&](const std::string& text) {
        if (!message || message_size == 0) return;
        const std::size_t n = std::min<std::size_t>(message_size - 1u, text.size());
        std::memcpy(message, text.data(), n);
        message[n] = '\0';
    };
    auto* session = static_cast<ProductionZoneSessionV0648110*>(context);
    if (!session) { set_message("context is required"); return 64; }
    {
        std::unique_lock<std::mutex> lock(session->mutex);
        if (!session->zone_loop_done) {
            set_message("radial zone loop must be complete before finalize"); return 65;
        }
        session->allowed_zone = session->completed_zone;
        session->cv.notify_all();
        session->cv.wait(lock, [&] { return session->finished; });
        if (session->rc != 0) {
            set_message(session->error.empty() ? "cpp-zone worker failed" : session->error);
            return session->rc;
        }
    }
    if (session->worker.joinable()) session->worker.join();
    set_message("ACCEPT");
    return 0;
}

extern "C" void xstar_production_zone_context_destroy_v0648110(void* context) {
    auto* session = static_cast<ProductionZoneSessionV0648110*>(context);
    if (!session) return;
    {
        std::lock_guard<std::mutex> lock(session->mutex);
        session->cancel = true;
        session->allowed_zone = 4000u;
    }
    session->cv.notify_all();
    if (session->worker.joinable()) session->worker.join();
    delete session;
}

// XSTAR-FUNCTION-COMMENT-BEGIN
// Purpose: Implement main in the standalone controller/front-end workflow without duplicating the scientific kernels.
// Reference context: XSTAR Manual ch14 for controller/radial workflow; implementation helper unless the called shared core performs the physics.
// XSTAR-FUNCTION-COMMENT-END
int main(int argc, char** argv) {
    Options options;
    std::string error;
    if (!parse_options(argc, argv, options, error)) {
        std::cerr << error << "\n";
        usage(std::cerr);
        return 2;
    }
    if (options.command == "help" || options.command == "--help" || options.command == "-h") {
        usage(std::cout);
        return 0;
    }
    if (options.command == "--version" || options.command == "-V") {
        std::cout << XSTAR_API_VERSION_STRING << "\n";
        return 0;
    }
    if (options.command == "list-backends") return command_list_backends();
    if (options.command == "backend-info") return command_backend_info(options);
    if (options.command == "self-test") return command_self_test(options);
    if (options.command == "element-self-test") return command_element_self_test(options, false, false);
    if (options.command == "evaluation-self-test") return command_element_self_test(options, true, false);
    if (options.command == "construction-self-test") return command_element_self_test(options, false, true);
    if (options.command == "construction-evaluation-self-test") return command_element_self_test(options, true, true);
    if (options.command == "spectral-self-test") return command_spectral_self_test(options);
    if (options.command == "thermal-self-test") return command_thermal_self_test(options);
    if (options.command == "convergence-self-test") return command_convergence_self_test(options);
    if (options.command == "secant-ieee-self-test") return command_secant_ieee_self_test(options);
    if (options.command == "trajectory-alignment-self-test") return command_trajectory_alignment_self_test(options);
    if (options.command == "controller-canonical-e7-self-test") return command_controller_canonical_e7_self_test(options);
    if (options.command == "fixed-state-self-test") return command_fixed_state_self_test(options, false);
    if (options.command == "run-fixed-state") return command_run_fixed_state(options);
    if (options.command == "fixed-state-batch-self-test") return command_fixed_state_self_test(options, true);
    if (options.command == "run-fixed-trajectory") return command_run_fixed_trajectory(options);
    if (options.command == "run-fixed-evaluation") return command_run_fixed_evaluation(options);
    if (options.command == "run") return command_run_physical(options);
    if (options.command == "standalone-capabilities") return command_standalone_capabilities();
    if (options.command == "run-standalone-case-probe-v70") return command_run_standalone_case_probe(options);
    if (options.command == "run-production") return command_run_standalone_production(options, std::filesystem::path(argv[0]));
    if (options.command == "run-production-assets") return command_run_native_resumable_trajectory(options, true);
    if (options.command == "run-native-reconstructed-products") return command_run_native_reconstructed_products(options);
    if (options.command == "run-fixed-dsec") return command_run_fixed_dsec(options);
    if (options.command == "production-self-test") return command_production_self_test(options);
    if (options.command == "production-batch-self-test") return command_production_batch_self_test(options);
    if (options.command == "run-compiled-case") return command_run_compiled_case(options);
    if (options.command == "run-zone") return command_run_zone(options);
    if (options.command == "python-bridge-test") return command_python_bridge_test(options);
    std::cerr << "unknown command: " << options.command << "\n";
    usage(std::cerr);
    return 2;
}
